window.VOCES={"autores":[{"s":"seneca","n":"Séneca","r":"/recursos/voces-que-nos-habitan/autores/seneca/","y":"c. 4 a. C.–65","e":"fil","en":"Filosofía","p":"clasico","d":["Filosofía","Ética"]},{"s":"marco-aurelio","n":"Marco Aurelio","r":"/recursos/voces-que-nos-habitan/autores/marco-aurelio/","y":"121–180","e":"fil","en":"Filosofía","p":"clasico","d":["Filosofía","Ética"]},{"s":"sigmund-freud","n":"Sigmund Freud","r":"/recursos/voces-que-nos-habitan/autores/sigmund-freud/","y":"1856–1939","e":"pa","en":"Psicoanálisis","p":"moderno","d":["Psicoanálisis","Medicina","Psicología"]},{"s":"william-james","n":"William James","r":"/recursos/voces-que-nos-habitan/autores/william-james/","y":"1842–1910","e":"ini","en":"Los comienzos","p":"moderno","d":["Psicología","Filosofía","Medicina"]}],"temas":{"sufrimiento":["Sufrimiento",true],"tiempo":["El tiempo",false],"conciencia":["Conciencia",true],"vinculos":["Vínculos",true],"sentido-de-vida":["Sentido de la vida",true],"identidad":["Identidad",true],"muerte":["La muerte",true],"cambio":["Cambio",true],"presencia":["Presencia",true],"habitos":["Hábitos",true],"aceptacion":["Aceptación",true],"autoconocimiento":["Autoconocimiento",true],"atencion":["Atención",true],"deseo":["Deseo",true],"inconsciente":["Lo inconsciente",false],"cultura":["Cultura",false],"felicidad":["Felicidad",false],"responsabilidad":["Responsabilidad",true],"encuentro":["El encuentro",true],"ira":["Ira y agresión",true],"verdad":["La verdad",true],"alegria":["Alegría",false],"educacion":["Aprender y enseñar",false],"amor":["Amor",false],"sociedad":["Sociedad",false],"resiliencia":["Resiliencia",false],"trabajo":["Trabajo",false],"regulacion-emocional":["Regulación emocional",false],"transformacion-personal":["Transformación personal",false],"angustia":["Angustia",false],"trascendencia":["Trascendencia",false],"incertidumbre":["Incertidumbre",false],"desarrollo-humano":["Desarrollo humano",false],"culpa":["Culpa",false],"libertad":["Libertad",false],"miedo":["Miedo",false],"autenticidad":["Autenticidad",false],"terapia":["Terapia",false],"comunicacion":["Comunicación",false],"amistad":["Amistad",false],"compasion":["Compasión",false],"cuerpo":["El cuerpo",false],"infancia":["Infancia",false],"duelo":["Duelo",false],"perdida":["Pérdida",false],"poder":["Poder",false],"conocimiento":["Conocimiento",false],"suenos":["Sueños",false],"voluntad":["Voluntad",false],"emociones":["Emociones",false],"silencio":["Silencio",false],"naturaleza":["Naturaleza",false],"existencia":["Existencia",false],"autoestima":["Autoestima",false],"esperanza":["Esperanza",false],"tristeza":["Tristeza",false],"gratitud":["Gratitud",false],"conexion":["Conexión",false],"tecnologia":["Tecnología",false],"familia":["Familia",false],"repeticion":["Repetición",false],"memoria":["Memoria",false],"trauma":["Trauma",false],"creatividad":["Creatividad",false],"soledad":["Soledad",false],"salud-mental":["Salud mental",false],"humor":["Humor",false],"empatia":["Empatía",false]},"citas":[{"i":"seneca-001","a":"seneca","t":"Hacelo así, querido Lucilio: reclamate para vos mismo.","o":"Ita fac, mi Lucili: vindica te tibi","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 1","te":["autoconocimiento","libertad","tiempo"]},{"i":"seneca-002","a":"seneca","t":"Una gran parte de la vida se escapa haciendo mal, la mayor parte sin hacer nada, y la vida entera haciendo otra cosa.","o":"magna pars vitae elabitur male agentibus, maxima nihil agentibus, tota vita aliud agentibus","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 1","te":["tiempo","sentido-de-vida"]},{"i":"seneca-003","a":"seneca","t":"¿A quién podrás mostrarme que le dé algún valor al tiempo, que aprecie cada día, que entienda que muere cada día?","o":"Quem mihi dabis qui aliquod pretium tempori ponat, qui diem aestimet, qui intellegat se cotidie mori?","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 2","te":["tiempo","muerte"]},{"i":"seneca-004","a":"seneca","t":"Todo el tiempo que quedó atrás ya lo tiene la muerte.","o":"quidquid aetatis retro est mors tenet","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 2","te":["tiempo","muerte"]},{"i":"seneca-005","a":"seneca","t":"Mientras se la posterga, la vida pasa.","o":"Dum differtur vita transcurrit.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 3","te":["tiempo","cambio"]},{"i":"seneca-006","a":"seneca","t":"Todo, Lucilio, es ajeno: solo el tiempo es nuestro.","o":"Omnia, Lucili, aliena sunt, tempus tantum nostrum est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 3","te":["tiempo","libertad"]},{"i":"seneca-007","a":"seneca","t":"No está en ninguna parte quien está en todas.","o":"Nusquam est qui ubique est.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 2, 2","te":["presencia","atencion"]},{"i":"seneca-008","a":"seneca","t":"No es pobre quien tiene poco, sino quien desea más.","o":"non qui parum habet, sed qui plus cupit, pauper est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 2, 6","te":["deseo","felicidad"]},{"i":"seneca-009","a":"seneca","t":"Deliberá todo con tu amigo, pero antes deliberá sobre él.","o":"Tu vero omnia cum amico delibera, sed de ipso prius","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 3, 2","te":["amistad","vinculos"]},{"i":"seneca-010","a":"seneca","t":"Las dos cosas son un error: confiar en todos y no confiar en nadie.","o":"utrumque enim vitium est, et omnibus credere et nulli","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 3, 4","te":["vinculos","amistad"]},{"i":"seneca-011","a":"seneca","t":"Ningún bien se disfruta si no se lo comparte.","o":"nullius boni sine socio iucunda possessio est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 6, 4","te":["amistad","alegria","encuentro"]},{"i":"seneca-012","a":"seneca","t":"Más te servirán la voz viva y la convivencia que los discursos.","o":"Plus tamen tibi et viva vox et convictus quam oratio proderit","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 6, 5","te":["encuentro","educacion"]},{"i":"seneca-013","a":"seneca","t":"Retirate en vos mismo cuanto puedas; tratá con quienes te harán mejor y recibí a quienes vos podés hacer mejores.","o":"Recede in te ipse quantum potes; cum his versare qui te meliorem facturi sunt, illos admitte quos tu potes facere meliores.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 7, 8","te":["vinculos","autoconocimiento","transformacion-personal"]},{"i":"seneca-014","a":"seneca","t":"Esto es recíproco: los seres humanos, mientras enseñan, aprenden.","o":"Mutuo ista fiunt, et homines dum docent discunt.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 7, 8","te":["educacion","encuentro"]},{"i":"seneca-015","a":"seneca","t":"Para tener por quién morir, para tener a quién seguir al exilio. (Respuesta a “¿para qué buscás un amigo?”)","o":"Ut habeam pro quo mori possim, ut habeam quem in exsilium sequar","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 9, 10","te":["amistad","amor"]},{"i":"seneca-016","a":"seneca","t":"Son más, Lucilio, las cosas que nos asustan que las que nos aplastan, y sufrimos más a menudo por la opinión que por la realidad.","o":"Plura sunt, Lucili, quae nos terrent quam quae premunt, et saepius opinione quam re laboramus.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 13, 4","te":["miedo","sufrimiento","angustia"]},{"i":"seneca-017","a":"seneca","t":"Algunas cosas nos atormentan más de lo que deberían, otras antes de lo que deberían, y otras cuando no deberían atormentarnos en absoluto.","o":"Quaedam ergo nos magis torquent quam debent, quaedam ante torquent quam debent, quaedam torquent cum omnino non debeant","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 13, 5","te":["angustia","miedo","sufrimiento"]},{"i":"seneca-018","a":"seneca","t":"La filosofía no es un arte para el público ni hecho para la ostentación: no está en las palabras sino en los hechos.","o":"Non est philosophia populare artificium nec ostentationi paratum; non in verbis sed in rebus est.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 16, 3","te":["sentido-de-vida","autenticidad"]},{"i":"seneca-019","a":"seneca","t":"La naturaleza desea poco; la opinión, lo inmenso.","o":"Exiguum natura desiderat, opinio immensum.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 16, 8","te":["deseo","felicidad"]},{"i":"seneca-020","a":"seneca","t":"¿Qué es la sabiduría? Querer siempre lo mismo y rechazar siempre lo mismo.","o":"quid est sapientia? semper idem velle atque idem nolle.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 20, 5","te":["identidad","autenticidad"]},{"i":"seneca-021","a":"seneca","t":"Antes que nada, querido Lucilio, hacé esto: aprendé a alegrarte.","o":"Hoc ante omnia fac, mi Lucili: disce gaudere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 23, 3","te":["alegria","felicidad"]},{"i":"seneca-022","a":"seneca","t":"La verdadera alegría es una cosa seria.","o":"verum gaudium res severa est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 23, 4","te":["alegria","felicidad"]},{"i":"seneca-023","a":"seneca","t":"Quien dice esto [“meditá sobre la muerte”] nos manda meditar sobre la libertad. Quien aprendió a morir desaprendió a servir.","o":"qui hoc dicit meditari libertatem iubet. Qui mori didicit servire dedidicit","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 26, 10","te":["muerte","libertad"]},{"i":"seneca-024","a":"seneca","t":"Una mente buena no se presta ni se compra.","o":"Bona mens nec commodatur nec emitur","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 27, 8","te":["autoconocimiento","transformacion-personal"]},{"i":"seneca-025","a":"seneca","t":"Morimos cada día: cada día se nos quita una parte de la vida, y aun cuando crecemos, la vida decrece.","o":"Cotidie morimur; cotidie enim demitur aliqua pars vitae, et tunc quoque cum crescimus vita decrescit.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 24, 20","te":["muerte","tiempo","cambio"]},{"i":"seneca-026","a":"seneca","t":"Tenés que cambiar de ánimo, no de cielo.","o":"Animum debes mutare, non caelum.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 28, 1","te":["transformacion-personal","cambio"]},{"i":"seneca-027","a":"seneca","t":"¿Te preguntás por qué esa huida no te ayuda? Huís con vos mismo.","o":"Quaeris quare te fuga ista non adiuvet? tecum fugis.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 28, 2","te":["autoconocimiento","cambio","sufrimiento"]},{"i":"seneca-028","a":"seneca","t":"Dios está cerca de vos, está con vos, está adentro.","o":"prope est a te deus, tecum est, intus est.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 41, 1","te":["trascendencia","conciencia"]},{"i":"seneca-029","a":"seneca","t":"Dentro de nosotros habita un espíritu sagrado, observador y guardián de nuestros males y nuestros bienes.","o":"sacer intra nos spiritus sedet, malorum bonorumque nostrorum observator et custos","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 41, 2","te":["conciencia","trascendencia"]},{"i":"seneca-030","a":"seneca","t":"“Son esclavos”. No: son seres humanos.","o":"'Servi sunt.' Immo homines.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 47, 1","te":["sociedad","encuentro"]},{"i":"seneca-031","a":"seneca","t":"Si querés vivir para vos, tenés que vivir para otro.","o":"alteri vivas oportet, si vis tibi vivere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 48, 2","te":["vinculos","sentido-de-vida","encuentro"]},{"i":"seneca-032","a":"seneca","t":"Nuestro mal no viene de afuera: está dentro de nosotros, asentado en las mismas entrañas.","o":"non est extrinsecus malum nostrum: intra nos est, in visceribus ipsis sedet","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 50, 4","te":["sufrimiento","autoconocimiento"]},{"i":"seneca-033","a":"seneca","t":"Nadie es lo bastante fuerte para salir a flote solo: hace falta que alguien le tienda la mano, que alguien lo saque.","o":"Nemo per se satis valet ut emergat; oportet manum aliquis porrigat, aliquis educat.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 52, 2","te":["vinculos","terapia","resiliencia"]},{"i":"seneca-034","a":"seneca","t":"Que los ojos no estén secos al perder a un amigo, ni desborden: hay que llorar, no lamentarse a gritos.","o":"Nec sicci sint oculi amisso amico nec fluant; lacrimandum est, non plorandum.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 63, 1","te":["duelo","tristeza","perdida"]},{"i":"seneca-035","a":"seneca","t":"Aquel a quien creés perdido, solo se adelantó.","o":"quem putas perisse praemissus est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 7","te":["duelo","muerte","perdida"]},{"i":"seneca-036","a":"seneca","t":"Nadie muere sino en su día.","o":"nemo nisi suo die moritur","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 69, 6","te":["muerte"]},{"i":"seneca-037","a":"seneca","t":"Lo bueno no es vivir, sino vivir bien.","o":"non enim vivere bonum est, sed bene vivere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 70, 4","te":["sentido-de-vida"]},{"i":"seneca-038","a":"seneca","t":"Para quien no sabe a qué puerto se dirige, ningún viento es favorable.","o":"ignoranti quem portum petat nullus suus ventus est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 71, 3","te":["sentido-de-vida","incertidumbre"]},{"i":"seneca-039","a":"seneca","t":"Hay que aprender mientras no sepas; y si creemos al proverbio, mientras vivas.","o":"Tamdiu discendum est quamdiu nescias; si proverbio credimus, quamdiu vivas.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 74, 3","te":["educacion","desarrollo-humano"]},{"i":"seneca-040","a":"seneca","t":"El dolor es leve si la opinión no le agrega nada.","o":"levis est dolor si nihil illi opinio adiecerit","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 74, 13","te":["sufrimiento","aceptacion"]},{"i":"seneca-041","a":"seneca","t":"El ocio sin estudio es muerte y sepultura del ser humano vivo.","o":"otium sine litteris mors est et hominis vivi sepultura","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 3","te":["sentido-de-vida","educacion"]},{"i":"seneca-042","a":"seneca","t":"El ser humano, cosa sagrada para el ser humano.","o":"Homo, sacra res homini","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 33","te":["sociedad","encuentro"]},{"i":"seneca-043","a":"seneca","t":"Sufre más de lo necesario quien sufre antes de lo necesario.","o":"Plus dolet quam necesse est qui ante dolet quam necesse est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 8","te":["angustia","sufrimiento","miedo"]},{"i":"seneca-044","a":"seneca","t":"No tenés que estar en otra parte, sino ser otro.","o":"non aliubi sis oportet sed alius","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 8","te":["transformacion-personal","cambio"]},{"i":"seneca-045","a":"seneca","t":"Considerá una gran cosa ser un solo hombre: ser siempre el mismo.","o":"Magnam rem puta unum hominem agere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 33","te":["identidad","autenticidad"]},{"i":"seneca-046","a":"seneca","t":"No es que tengamos poco tiempo, sino que perdemos mucho.","o":"Non exiguum temporis habemus, sed multum perdidimus.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"1, 3","te":["tiempo"]},{"i":"seneca-047","a":"seneca","t":"La vida, si sabés usarla, es larga.","o":"uita, si uti scias, longa est","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"2, 1","te":["tiempo","sentido-de-vida"]},{"i":"seneca-048","a":"seneca","t":"El mayor obstáculo para vivir es la espera, que depende del mañana y pierde el hoy.","o":"Maximum uiuendi impedimentum est exspectatio, quae pendet ex crastino, perdit hodiernum.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"9, 1","te":["tiempo","presencia"]},{"i":"seneca-049","a":"seneca","t":"Todo lo que vendrá está en lo incierto: viví ahora.","o":"Omnia quae uentura sunt in incerto iacent: protinus uiue.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"9, 1","te":["incertidumbre","presencia","tiempo"]},{"i":"seneca-050","a":"seneca","t":"A vivir hay que aprender toda la vida y, lo que quizás te asombre más, toda la vida hay que aprender a morir.","o":"uiuere tota uita discendum est et, quod magis fortasse miraberis, tota uita discendum est mori.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"7, 3","te":["muerte","desarrollo-humano","sentido-de-vida"]},{"i":"seneca-051","a":"seneca","t":"Nada es menos propio de una persona atareada que vivir: no hay ciencia más difícil.","o":"Nihil minus est hominis occupati quam uiuere: nullius rei difficilior scientia est.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"7, 3","te":["tiempo","trabajo","sentido-de-vida"]},{"i":"seneca-052","a":"seneca","t":"El mayor remedio de la ira es la demora.","o":"Maximum remedium irae mora est.","l":"la","ob":"Sobre la ira","an":"c. 41","u":"Libro 2, 29, 1","te":["ira","regulacion-emocional"]},{"i":"seneca-053","a":"seneca","t":"El fuego prueba el oro; la desgracia, a los valientes.","o":"Ignis aurum probat, miseria fortes uiros.","l":"la","ob":"Sobre la providencia","an":"c. 64","u":"5, 9","te":["resiliencia","sufrimiento"]},{"i":"marco-aurelio-001","a":"marco-aurelio","t":"Empezá la mañana diciéndote: hoy me voy a encontrar con el entrometido, el desagradecido, el arrogante, el mentiroso, el envidioso, el insociable.","o":"Begin the morning by saying to thyself, I shall meet with the busybody, the ungrateful, arrogant, deceitful, envious, unsocial.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 1","te":["vinculos","aceptacion"]},{"i":"marco-aurelio-002","a":"marco-aurelio","t":"Recordá cuánto tiempo hace que venís postergando estas cosas.","o":"Remember how long thou hast been putting off these things","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 4","te":["tiempo","cambio"]},{"i":"marco-aurelio-003","a":"marco-aurelio","t":"Nadie pierde otra vida que la que vive ahora, ni vive otra que la que ahora pierde.","o":"no man loses any other life than this which he now lives, nor lives any other than this which he now loses","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 14","te":["tiempo","presencia","muerte"]},{"i":"marco-aurelio-004","a":"marco-aurelio","t":"Cada uno vive solo este momento presente, que es un punto indivisible; todo lo demás de su vida ya pasó o es incierto.","o":"every man lives only this present time, which is an indivisible point, and that all the rest of his life is either past or it is uncertain","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 3, 10","te":["presencia","tiempo","incertidumbre"]},{"i":"marco-aurelio-005","a":"marco-aurelio","t":"En ningún lugar encuentra una persona un retiro más tranquilo y libre de inquietud que en su propia alma.","o":"nowhere either with more quiet or more freedom from trouble does a man retire than into his own soul","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 3","te":["silencio","presencia","autoconocimiento"]},{"i":"marco-aurelio-006","a":"marco-aurelio","t":"El universo es transformación; la vida, opinión.","o":"The universe is transformation: life is opinion.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 3","te":["cambio","conciencia"]},{"i":"marco-aurelio-007","a":"marco-aurelio","t":"Quitá tu opinión y se quita la queja “me hicieron daño”.","o":"Take away thy opinion, and then there is taken away the complaint, \"I have been harmed.\"","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 7","te":["sufrimiento","aceptacion"]},{"i":"marco-aurelio-008","a":"marco-aurelio","t":"No actúes como si fueras a vivir diez mil años. La muerte pende sobre vos. Mientras vivas, mientras esté en tu poder, sé bueno.","o":"Do not act as if thou wert going to live ten thousand years. Death hangs over thee. While thou livest, while it is in thy power, be good.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 17","te":["muerte","tiempo","responsabilidad"]},{"i":"marco-aurelio-009","a":"marco-aurelio","t":"Cuántas molestias se ahorra quien no mira lo que dice, hace o piensa el vecino, sino solo lo que hace él mismo.","o":"How much trouble he avoids who does not look to see what his neighbor says or does or thinks, but only to what he does himself","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 18","te":["autoconocimiento","responsabilidad"]},{"i":"marco-aurelio-010","a":"marco-aurelio","t":"Sé como el promontorio contra el que rompen sin cesar las olas: se mantiene firme y amansa la furia del agua a su alrededor.","o":"Be like the promontory against which the waves continually break, but it stands firm and tames the fury of the water around it.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 49","te":["resiliencia","regulacion-emocional"]},{"i":"marco-aurelio-011","a":"marco-aurelio","t":"Como sean tus pensamientos habituales, así será el carácter de tu mente: el alma se tiñe de sus pensamientos.","o":"Such as are thy habitual thoughts, such also will be the character of thy mind; for the soul is dyed by the thoughts.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 16","te":["conciencia","habitos","identidad"]},{"i":"marco-aurelio-012","a":"marco-aurelio","t":"La mejor manera de vengarte es no volverte como quien te hizo daño.","o":"The best way of avenging thyself is not to become like","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 6","te":["ira","vinculos"]},{"i":"marco-aurelio-013","a":"marco-aurelio","t":"Mirá hacia adentro. Adentro está la fuente del bien, y siempre brotará si siempre cavás.","o":"Look within. Within is the fountain of good, and it will ever bubble up, if thou wilt ever dig.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 59","te":["autoconocimiento","conciencia"]},{"i":"marco-aurelio-014","a":"marco-aurelio","t":"Si algo externo te duele, no es esa cosa la que te perturba, sino tu propio juicio sobre ella.","o":"If thou art pained by any external thing, it is not this thing that disturbs thee, but thy own judgment about it.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 8, 47","te":["sufrimiento","regulacion-emocional","conciencia"]},{"i":"marco-aurelio-015","a":"marco-aurelio","t":"No sigas discutiendo cómo debe ser un hombre bueno: selo.","o":"No longer talk at all about the kind of man that a good man ought to be, but be such.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 10, 16","te":["autenticidad","responsabilidad"]},{"i":"marco-aurelio-016","a":"marco-aurelio","t":"Considerá cuánto más dolor nos causan la ira y el fastidio por esos actos que los actos mismos.","o":"consider how much more pain is brought on us by the anger and vexation caused by such acts than by the acts themselves","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 11, 18","te":["ira","sufrimiento"]},{"i":"marco-aurelio-017","a":"marco-aurelio","t":"[Cada uno se ama más que a nadie, y sin embargo] valora menos su propia opinión sobre sí que la opinión de los demás.","o":"sets less value on his own opinion of himself than on the opinion of others","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 12, 4","te":["identidad","autenticidad"]},{"i":"marco-aurelio-018","a":"marco-aurelio","t":"Cuidate de no volverte un César, de no teñirte con ese tinte.","o":"Take care that thou art not made into a Caesar, that thou art not dyed with this dye","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 30","te":["poder","identidad"]},{"i":"marco-aurelio-019","a":"marco-aurelio","t":"La perfección del carácter consiste en vivir cada día como si fuera el último.","o":"The perfection of moral character consists in this, in passing every day as the last","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 69","te":["muerte","presencia"]},{"i":"marco-aurelio-020","a":"marco-aurelio","t":"Los seres humanos existen los unos para los otros. Enseñales, entonces, o soportalos.","o":"Men exist for the sake of one another. Teach them then, or bear with them.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 8, 59","te":["vinculos","aceptacion"]},{"i":"marco-aurelio-021","a":"marco-aurelio","t":"Lo que es obstáculo en el camino nos ayuda en ese camino.","o":"that which is an obstacle on the road helps us on this road","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 20","te":["resiliencia","cambio"]},{"i":"marco-aurelio-022","a":"marco-aurelio","t":"Cuando te ofenda la desvergüenza de alguien, preguntate enseguida: ¿es posible que no haya desvergonzados en el mundo? No es posible.","o":"When thou art offended with any man's shameless conduct, immediately ask thyself, Is it possible, then, that shameless men should not be in the world? It is not possible.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 42","te":["aceptacion","ira"]},{"i":"marco-aurelio-023","a":"marco-aurelio","t":"Que no te perturbe lo que vendrá: llegarás a ello, si hace falta, con la misma razón que hoy usás para lo presente.","o":"Let not future things disturb thee, for thou wilt come to them, if it shall be necessary, having with thee the same reason which now thou usest for present things.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 8","te":["incertidumbre","angustia","presencia"]},{"i":"marco-aurelio-024","a":"marco-aurelio","t":"Puesto que es posible que dejes la vida en este mismo momento, regulá cada acto y cada pensamiento en consecuencia.","o":"Since it is possible that thou mayest depart from life this very moment, regulate every act and thought accordingly.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 11","te":["muerte","presencia"]},{"i":"marco-aurelio-025","a":"marco-aurelio","t":"“Ocupate de pocas cosas si querés estar tranquilo”, dice el filósofo. Pero pensá si no sería mejor decir: hacé lo necesario.","o":"Occupy thyself with few things, says the philosopher, if thou wouldst be tranquil.--But consider if it would not be better to say, Do what is necessary","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 24","te":["presencia","trabajo"]},{"i":"marco-aurelio-026","a":"marco-aurelio","t":"Si alguien puede convencerme y mostrarme que no pienso o no actúo bien, cambiaré con gusto: busco la verdad, y nadie fue jamás dañado por ella.","o":"If any man is able to convince me and show me that I do not think or act right, I will gladly change; for I seek the truth, by which no man was ever injured.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 21","te":["verdad","cambio","transformacion-personal"]},{"i":"marco-aurelio-027","a":"marco-aurelio","t":"No malgastes lo que te queda de vida en pensamientos sobre los demás.","o":"Do not waste the remainder of thy life in thoughts about others","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 3, 4","te":["tiempo","autoconocimiento"]},{"i":"marco-aurelio-028","a":"marco-aurelio","t":"A la mañana, cuando te levantes de mala gana, tené presente este pensamiento: me levanto para hacer la obra de un ser humano.","o":"In the morning when thou risest unwillingly, let this thought be present,--I am rising to the work of a human being.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 1","te":["trabajo","sentido-de-vida"]},{"i":"marco-aurelio-029","a":"marco-aurelio","t":"Es propio del ser humano amar incluso a quienes obran mal.","o":"It is peculiar to man to love even those who do wrong.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 22","te":["amor","compasion"]},{"i":"marco-aurelio-030","a":"marco-aurelio","t":"No te perturbes pensando en la totalidad de tu vida.","o":"Do not disturb thyself by thinking of the whole of thy life.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 8, 36","te":["angustia","presencia"]},{"i":"marco-aurelio-031","a":"marco-aurelio","t":"Cuando quieras alegrarte, pensá en las virtudes de quienes viven con vos.","o":"When thou wishest to delight thyself, think of the virtues of those who live with thee","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 48","te":["alegria","vinculos","gratitud"]},{"i":"marco-aurelio-032","a":"marco-aurelio","t":"Todas las cosas están entrelazadas unas con otras, y el lazo es sagrado.","o":"All things are implicated with one another, and the bond is holy","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 9","te":["conexion","naturaleza"]},{"i":"marco-aurelio-033","a":"marco-aurelio","t":"De la vida humana, el tiempo es un punto y la sustancia, un flujo.","o":"Of human life the time is a point, and the substance is in a flux","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 17","te":["tiempo","cambio"]},{"i":"marco-aurelio-034","a":"marco-aurelio","t":"Si algo te resulta difícil de lograr, no pienses que es imposible para el ser humano.","o":"If a thing is difficult to be accomplished by thyself, do not think that it is impossible for man","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 19","te":["resiliencia"]},{"i":"marco-aurelio-035","a":"marco-aurelio","t":"No desprecies la muerte: aceptala de buen grado, porque también ella es una de las cosas que la naturaleza quiere.","o":"Do not despise death, but be well content with it, since this too is one of those things which nature wills.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 3","te":["muerte","aceptacion","naturaleza"]},{"i":"marco-aurelio-036","a":"marco-aurelio","t":"Si alguien se equivoca, enseñale con amabilidad y mostrale su error.","o":"If a man is mistaken, instruct him kindly and show him his error.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 10, 4","te":["comunicacion","compasion"]},{"i":"marco-aurelio-037","a":"marco-aurelio","t":"Considerá que también vos hacés muchas cosas mal, y que sos un ser humano como los demás.","o":"consider that thou also doest many things wrong, and that thou art a man like others","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 11, 18","te":["compasion","autoconocimiento"]},{"i":"marco-aurelio-038","a":"marco-aurelio","t":"Quien obra mal, obra mal contra sí mismo.","o":"He who does wrong does wrong against himself.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 4","te":["responsabilidad"]},{"i":"marco-aurelio-039","a":"marco-aurelio","t":"Tu opinión presente fundada en la comprensión, tu conducta presente orientada al bien común y tu disposición presente de contento con todo lo que sucede: eso basta.","o":"Thy present opinion founded on understanding, and thy present conduct directed to social good, and thy present disposition of contentment with everything which happens--that is enough.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 6","te":["presencia","aceptacion"]},{"i":"marco-aurelio-040","a":"marco-aurelio","t":"Que no te importe tener frío o calor si estás cumpliendo tu deber.","o":"Let it make no difference to thee whether thou art cold or warm, if thou art doing thy duty","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 2","te":["responsabilidad","trabajo"]},{"i":"marco-aurelio-041","a":"marco-aurelio","t":"Acostumbrate a atender con cuidado lo que dice otro y, en lo posible, a estar en la mente de quien habla.","o":"Accustom thyself to attend carefully to what is said by another, and as much as it is possible, be in the speaker's mind.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 53","te":["comunicacion","encuentro","atencion"]},{"i":"marco-aurelio-042","a":"marco-aurelio","t":"Borrá la fantasía. Detené el tirón de los hilos. Limitate al presente.","o":"Wipe out the imagination. Stop the pulling of the strings. Confine thyself to the present.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 29","te":["presencia","atencion"]},{"i":"marco-aurelio-043","a":"marco-aurelio","t":"A nadie le sucede nada que no esté formado por naturaleza para soportar.","o":"Nothing happens to any man which he is not formed by nature to bear.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 18","te":["resiliencia","aceptacion"]},{"i":"marco-aurelio-044","a":"marco-aurelio","t":"Todo dura solo un día: lo que recuerda y lo recordado.","o":"Everything is only for a day, both that which remembers and that which is remembered.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 35","te":["tiempo","muerte"]},{"i":"marco-aurelio-045","a":"marco-aurelio","t":"Amá el oficio que aprendiste, por modesto que sea, y contentate con él.","o":"Love the art, poor as it may be, which thou hast learned, and be content with it","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 31","te":["trabajo","aceptacion"]},{"i":"marco-aurelio-046","a":"marco-aurelio","t":"El arte de vivir se parece más al del luchador que al del bailarín.","o":"The art of life is more like the wrestler's art than the dancer's","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 61","te":["resiliencia","sentido-de-vida"]},{"i":"marco-aurelio-047","a":"marco-aurelio","t":"Que haya serenidad frente a lo que viene de una causa externa.","o":"Let there be freedom from perturbations with respect to the things which come from the external cause","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 31","te":["regulacion-emocional","aceptacion"]},{"i":"marco-aurelio-048","a":"marco-aurelio","t":"Retirate en vos mismo. La razón que gobierna tiene esta naturaleza: se contenta consigo cuando obra con justicia, y así asegura la tranquilidad.","o":"Retire into thyself. The rational principle which rules has this nature, that it is content with itself when it does what is just, and so secures tranquillity.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 28","te":["silencio","autoconocimiento"]},{"i":"marco-aurelio-049","a":"marco-aurelio","t":"No es justo ofenderse con los demás: tu deber es cuidarlos y soportarlos con dulzura.","o":"it is no way right to be offended with men, but it is thy duty to care for them and to bear with them gently","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 3","te":["vinculos","compasion"]},{"i":"marco-aurelio-050","a":"marco-aurelio","t":"Qué ridículo y qué extraño a la vida es quien se sorprende de cualquier cosa que sucede en ella.","o":"How ridiculous and what a stranger he is who is surprised at anything which happens in life.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 12, 13","te":["aceptacion","existencia"]},{"i":"sigmund-freud-001","a":"sigmund-freud","t":"La intención de que el ser humano sea “feliz” no está contenida en el plan de la “Creación”.","o":"die Absicht, daß der Mensch \"glücklich\" sei, ist im Plan der \"Schöpfung\" nicht enthalten","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["felicidad","sufrimiento"]},{"i":"sigmund-freud-002","a":"sigmund-freud","t":"El sufrimiento nos amenaza desde tres lados: desde el propio cuerpo, condenado a la decadencia y la disolución, que ni siquiera puede prescindir del dolor y la angustia como señales de alarma; desde el mundo exterior, que puede abatirse sobre nosotros con fuerzas hiperpotentes, implacables y destructivas; y por último, desde los vínculos con otros seres humanos.","o":"Von drei Seiten droht das Leiden, vom eigenen Körper her, der, zu Verfall und Auflösung bestimmt, sogar Schmerz und Angst als Warnungssignale nicht entbehren kann, von der Außenwelt, die mit übermächtigen, unerbittlichen, zerstörenden Kräften gegen uns wüten kann, und endlich aus den Beziehungen zu anderen Menschen.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","vinculos","cuerpo"]},{"i":"sigmund-freud-003","a":"sigmund-freud","t":"El sufrimiento que proviene de esta fuente [los vínculos] lo sentimos quizás más dolorosamente que cualquier otro.","o":"Das Leiden, das aus dieser Quelle stammt, empfinden wir vielleicht schmerzlicher als jedes andere","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","vinculos"]},{"i":"sigmund-freud-004","a":"sigmund-freud","t":"Nunca estamos más desprotegidos frente al sufrimiento que cuando amamos; nunca más desamparadamente infelices que cuando perdimos al objeto amado o su amor.","o":"Niemals sind wir ungeschützter gegen das Leiden, als wenn wir lieben, niemals hilfloser unglücklich, als wenn wir das geliebte Objekt oder seine Liebe verloren haben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["amor","perdida","duelo"]},{"i":"sigmund-freud-005","a":"sigmund-freud","t":"La vida, tal como nos es impuesta, resulta demasiado pesada: nos trae demasiados dolores, desengaños, tareas insolubles.","o":"Das Leben, wie es uns auferlegt ist, ist zu schwer für uns, es bringt uns zuviel Schmerzen, Enttäuschungen, unlösbare Aufgaben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","existencia"]},{"i":"sigmund-freud-006","a":"sigmund-freud","t":"El ser humano se ha convertido, por así decir, en una especie de dios con prótesis: bastante magnífico cuando se coloca todos sus órganos auxiliares, pero estos no se le han integrado.","o":"Der Mensch ist sozusagen eine Art Prothesengott geworden, recht großartig, wenn er alle seine Hilfsorgane anlegt, aber sie sind nicht mit ihm verwachsen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 3","te":["tecnologia","cultura"]},{"i":"sigmund-freud-007","a":"sigmund-freud","t":"La felicidad, en ese sentido moderado en que se la reconoce posible, es un problema de la economía libidinal de cada individuo.","o":"Das Glück in jenem ermäßigten Sinn, in dem es als möglich erkannt wird, ist ein Problem der individuellen Libidoökonomie.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["felicidad","deseo"]},{"i":"sigmund-freud-008","a":"sigmund-freud","t":"El goce de la belleza tiene un carácter sensorial particular, suavemente embriagador.","o":"Der Genuß an der Schönheit hat einen besonderen, milde berauschenden Empfindungscharakter.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["alegria","cultura"]},{"i":"sigmund-freud-009","a":"sigmund-freud","t":"La utilidad de la belleza no es evidente, su necesidad cultural no se ve, y sin embargo la cultura no podría prescindir de ella.","o":"Ein Nutzen der Schönheit liegt nicht klar zutage, ihre kulturelle Notwendigkeit ist nicht einzusehen, und doch könnte man sie in der Kultur nicht vermissen.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["cultura"]},{"i":"sigmund-freud-010","a":"sigmund-freud","t":"Esta actitud estética ante la meta de la vida protege poco contra los sufrimientos que amenazan, pero puede compensar muchas cosas.","o":"Diese ästhetische Einstellung zum Lebensziel bietet wenig Schutz gegen drohende Leiden, vermag aber für vieles zu entschädigen.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","cultura"]},{"i":"sigmund-freud-011","a":"sigmund-freud","t":"Quien emprende este camino hacia la felicidad [rehacer el mundo según sus deseos] con una rebeldía desesperada, por lo general no logrará nada: la realidad es demasiado fuerte para él.","o":"Wer in verzweifelter Empörung diesen Weg zum Glück einschlägt, wird in der Regel nichts erreichen; die Wirklichkeit ist zu stark für ihn.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["felicidad","deseo"]},{"i":"sigmund-freud-012","a":"sigmund-freud","t":"La tarea es desplazar las metas pulsionales de manera que la frustración que impone el mundo exterior no pueda alcanzarlas.","o":"Die zu lösende Aufgabe ist, die Triebziele solcherart zu verlegen, daß sie von der Versagung der Außenwelt nicht getroffen werden können.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["deseo","sufrimiento"]},{"i":"sigmund-freud-013","a":"sigmund-freud","t":"Y sin embargo, las personas valoran poco el trabajo como camino hacia la felicidad.","o":"Und dennoch wird Arbeit als Weg zum Glück von den Menschen wenig geschätzt.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["trabajo","felicidad"]},{"i":"sigmund-freud-014","a":"sigmund-freud","t":"El ser humano civilizado cambió una parte de posibilidad de felicidad por una parte de seguridad.","o":"Der Kulturmensch hat für ein Stück Glücksmöglichkeit ein Stück Sicherheit eingetauscht.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["cultura","felicidad","sociedad"]},{"i":"sigmund-freud-015","a":"sigmund-freud","t":"La cultura tiene que movilizarlo todo para poner límites a las pulsiones agresivas de los seres humanos.","o":"Die Kultur muß alles aufbieten, um den Aggressionstrieben der Menschen Schranken zu setzen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["cultura","ira","sociedad"]},{"i":"sigmund-freud-016","a":"sigmund-freud","t":"Siempre es posible ligar amorosamente entre sí a una multitud mayor de personas, con tal de que queden otras para manifestarles la agresión.","o":"Es ist immer möglich, eine größere Menge von Menschen in Liebe aneinander zu binden, wenn nur andere für die Äußerung der Aggression übrigbleiben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["sociedad","ira","poder"]},{"i":"sigmund-freud-017","a":"sigmund-freud","t":"Las pasiones pulsionales son más fuertes que los intereses racionales.","o":"triebhafte Leidenschaften sind stärker als vernünftige Interessen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["deseo","sociedad"]},{"i":"sigmund-freud-018","a":"sigmund-freud","t":"La agresión es introyectada, interiorizada, en verdad devuelta al lugar de donde vino: vuelta contra el propio yo.","o":"Die Aggression wird introjiziert, verinnerlicht, eigentlich aber dorthin zurückgeschickt, woher sie gekommen ist, also gegen das eigene Ich gewendet.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","ira","inconsciente"]},{"i":"sigmund-freud-019","a":"sigmund-freud","t":"A la tensión entre el severo superyó y el yo que le está sometido la llamamos conciencia de culpa; se manifiesta como necesidad de castigo.","o":"Die Spannung zwischen dem gestrengen Über-Ich und dem ihm unterworfenen Ich heißen wir Schuldbewußtsein; sie äußert sich als Strafbedürfnis.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","inconsciente"]},{"i":"sigmund-freud-020","a":"sigmund-freud","t":"Lo malo es, al principio, aquello por lo cual se nos amenaza con la pérdida del amor; por angustia ante esa pérdida hay que evitarlo.","o":"Das Böse ist also anfänglich dasjenige, wofür man mit Liebesverlust bedroht wird; aus Angst vor diesem Verlust muß man es vermeiden.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","miedo","amor"]},{"i":"sigmund-freud-021","a":"sigmund-freud","t":"La agresión de la conciencia moral conserva la agresión de la autoridad.","o":"Die Aggression des Gewissens konserviert die Aggression der Autorität.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","poder"]},{"i":"sigmund-freud-022","a":"sigmund-freud","t":"Las religiones, al menos, nunca desconocieron el papel del sentimiento de culpa en la cultura.","o":"Die Religionen wenigstens haben die Rolle des Schuldgefühls in der Kultur nie verkannt.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 8","te":["culpa","cultura","trascendencia"]},{"i":"sigmund-freud-023","a":"sigmund-freud","t":"Eros y Ananké [amor y necesidad] se convirtieron también en los padres de la cultura humana.","o":"Eros und Ananke sind auch die Eltern der menschlichen Kultur geworden.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 4","te":["amor","cultura"]},{"i":"sigmund-freud-024","a":"sigmund-freud","t":"[Mi propósito era] presentar el sentimiento de culpa como el problema más importante del desarrollo cultural.","o":"das Schuldgefühl als das wichtigste Problem der Kulturentwicklung hinzustellen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 8","te":["culpa","cultura"]},{"i":"sigmund-freud-025","a":"sigmund-freud","t":"No sabría indicar una necesidad de la infancia tan intensa como la de la protección paterna.","o":"Ein ähnlich starkes Bedürfnis aus der Kindheit wie das nach dem Vaterschutz wüßte ich nicht anzugeben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 1","te":["familia","infancia"]},{"i":"sigmund-freud-026","a":"sigmund-freud","t":"El beneficio del orden es innegable: permite al ser humano aprovechar mejor el espacio y el tiempo, mientras ahorra sus fuerzas psíquicas.","o":"Die Wohltat der Ordnung ist ganz unleugbar, sie ermöglicht dem Menschen die beste Ausnützung von Raum und Zeit, während sie seine psychischen Kräfte schont.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 3","te":["habitos","cultura"]},{"i":"sigmund-freud-027","a":"sigmund-freud","t":"El orden es una especie de compulsión de repetición que, establecida una vez, decide cuándo, dónde y cómo debe hacerse algo.","o":"Die Ordnung ist eine Art Wiederholungszwang, die durch einmalige Einrichtung entscheidet, wann, wo und wie etwas getan werden soll","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 3","te":["habitos","inconsciente"]},{"i":"sigmund-freud-028","a":"sigmund-freud","t":"El amor de meta inhibida fue en su origen amor plenamente sensual, y lo sigue siendo en lo inconsciente del ser humano.","o":"Die zielgehemmte Liebe war eben ursprünglich vollsinnliche Liebe und ist es im Unbewußten des Menschen noch immer.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 4","te":["amor","inconsciente","deseo"]},{"i":"sigmund-freud-029","a":"sigmund-freud","t":"La voz del intelecto es baja, pero no descansa hasta hacerse oír.","o":"die Stimme des Intellekts ist leise, aber sie ruht nicht, ehe sie sich Gehör geschafft hat","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["verdad","conciencia"]},{"i":"sigmund-freud-030","a":"sigmund-freud","t":"No, nuestra ciencia no es una ilusión. Pero sería una ilusión creer que podríamos obtener de otra parte lo que ella no puede darnos.","o":"Nein, unsere Wissenschaft ist keine Illusion. Eine Illusion aber wäre es zu glauben, daß wir anderswoher bekommen könnten, was sie uns nicht geben kann.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["verdad","conocimiento"]},{"i":"sigmund-freud-031","a":"sigmund-freud","t":"El ser humano no puede seguir siendo niño para siempre: tiene que salir, finalmente, a la “vida hostil”.","o":"Der Mensch kann nicht ewig Kind bleiben, er muß endlich hinaus ins \"feindliche Leben\".","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 8","te":["desarrollo-humano","infancia","responsabilidad"]},{"i":"sigmund-freud-032","a":"sigmund-freud","t":"No hay ninguna instancia por encima de la razón.","o":"Es gibt keine Instanz über der Vernunft.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 4","te":["verdad"]},{"i":"sigmund-freud-033","a":"sigmund-freud","t":"Como estamos dispuestos a renunciar a buena parte de nuestros deseos infantiles, podemos soportar que algunas de nuestras expectativas resulten ser ilusiones.","o":"Da wir bereit sind, auf ein gutes Stück unserer infantilen Wünsche zu verzichten, können wir es vertragen, wenn sich einige unserer Erwartungen als Illusionen herausstellen.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["deseo","aceptacion","desarrollo-humano"]},{"i":"sigmund-freud-034","a":"sigmund-freud","t":"Podemos insistir cuanto queramos en que el intelecto humano carece de fuerza frente a la vida pulsional, y tener razón.","o":"Wir mögen noch so oft betonen, der menschliche Intellekt sei kraftlos im Vergleich zum menschlichen Triebleben, und recht damit haben.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["deseo","conciencia"]},{"i":"sigmund-freud-035","a":"sigmund-freud","t":"El yo es, ante todo, un yo corporal: no es solo un ser de superficie, sino él mismo la proyección de una superficie.","o":"Das Ich ist vor allem ein körperliches, es ist nicht nur ein Oberflächenwesen, sondern selbst die Projektion einer Oberfläche.","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 2","te":["identidad","cuerpo"]},{"i":"sigmund-freud-036","a":"sigmund-freud","t":"El yo es la verdadera sede de la angustia.","o":"Das Ich ist ja die eigentliche Angststätte.","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 5","te":["angustia","identidad"]},{"i":"sigmund-freud-037","a":"sigmund-freud","t":"[Vemos] al mismo yo como una pobre criatura, sometida a tres servidumbres y que, por eso, sufre la amenaza de tres peligros.","o":"dasselbe Ich als armes Ding, welches unter dreierlei Dienstbarkeiten steht und demzufolge unter den Drohungen von dreierlei Gefahren leidet","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 5","te":["identidad","sufrimiento"]},{"i":"sigmund-freud-038","a":"sigmund-freud","t":"El psicoanálisis es un instrumento que debe permitirle al yo la conquista progresiva del ello.","o":"Die Psychoanalyse ist ein Werkzeug, welches dem Ich die fortschreitende Eroberung des Es ermöglichen soll.","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 5","te":["terapia","inconsciente"]},{"i":"sigmund-freud-039","a":"sigmund-freud","t":"[El yo] ni siquiera es dueño en su propia casa, sino que depende de escasas noticias sobre lo que ocurre de manera inconsciente en su vida anímica.","o":"daß es nicht einmal Herr ist im eigenen Hause, sondern auf kärgliche Nachrichten angewiesen bleibt von dem, was unbewußt in seinem Seelenleben vorgeht","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 18","te":["inconsciente","identidad","autoconocimiento"]},{"i":"sigmund-freud-040","a":"sigmund-freud","t":"Las palabras fueron en su origen magia, y la palabra conserva todavía hoy mucho de su antiguo poder mágico.","o":"Worte waren ursprünglich Zauber, und das Wort hat noch heute viel von seiner alten Zauberkraft bewahrt.","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 1","te":["comunicacion","terapia"]},{"i":"sigmund-freud-041","a":"sigmund-freud","t":"Con palabras una persona puede hacer dichosa a otra o empujarla a la desesperación.","o":"Durch Worte kann ein Mensch den anderen selig machen oder zur Verzweiflung treiben","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 1","te":["comunicacion","vinculos"]},{"i":"sigmund-freud-042","a":"sigmund-freud","t":"En el tratamiento analítico no ocurre otra cosa que un intercambio de palabras entre el analizado y el médico.","o":"In der analytischen Behandlung geht nichts anderes vor als ein Austausch von Worten zwischen dem Analysierten und dem Arzt.","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 1","te":["terapia","comunicacion"]},{"i":"sigmund-freud-043","a":"sigmund-freud","t":"Los sentimientos hostiles significan un lazo afectivo tanto como los tiernos.","o":"Die feindlichen Gefühle bedeuten ebenso eine Gefühlsbindung wie die zärtlichen","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 27","te":["vinculos","ira","amor"]},{"i":"sigmund-freud-047","a":"sigmund-freud","t":"Donde era ello, ha de advenir yo. Es un trabajo de cultura, como la desecación del Zuiderzee.","o":"Wo Es war, soll Ich werden. Es ist Kulturarbeit etwa wie die Trockenlegung der Zuydersee.","l":"de","ob":"Nuevas conferencias de introducción al psicoanálisis","an":"1933","u":"Capítulo 3","te":["inconsciente","terapia","transformacion-personal"]},{"i":"sigmund-freud-044","a":"sigmund-freud","t":"La interpretación de los sueños es la vía regia hacia el conocimiento de lo inconsciente en la vida anímica.","o":"Die Traumdeutung aber ist die Via regia zur Kenntnis des Unbewußten im Seelenleben.","l":"de","ob":"La interpretación de los sueños","an":"1900","u":"Capítulo 7","te":["suenos","inconsciente"]},{"i":"sigmund-freud-045","a":"sigmund-freud","t":"El sueño es el cumplimiento (disfrazado) de un deseo (sofocado, reprimido).","o":"Der Traum ist die (verkleidete) Erfüllung eines (unterdrückten, verdrängten) Wunsches","l":"de","ob":"La interpretación de los sueños","an":"1900","u":"Capítulo 4","te":["suenos","deseo","inconsciente"]},{"i":"sigmund-freud-046","a":"sigmund-freud","t":"La meta de toda vida es la muerte.","o":"Das Ziel alles Lebens ist der Tod","l":"de","ob":"Más allá del principio del placer","an":"1920","u":"Capítulo 5","te":["muerte"]},{"i":"sigmund-freud-050","a":"sigmund-freud","t":"El psicoanálisis consideró desde el comienzo que ese destino [que parece perseguir a algunas personas] es en gran parte autoprovocado y está determinado por influencias de la primera infancia.","o":"die Psychoanalyse hat vom Anfang an solches Schicksal für zum großen Teil selbstbereitet und durch frühinfantile Einflüsse determiniert gehalten","l":"de","ob":"Más allá del principio del placer","an":"1920","u":"Capítulo 3","te":["repeticion","infancia","inconsciente"]},{"i":"sigmund-freud-048","a":"sigmund-freud","t":"Nuestras enfermas histéricas sufren de reminiscencias.","o":"Unsere hysterisch Kranken leiden an Reminiszenzen.","l":"de","ob":"Sobre psicoanálisis (Cinco conferencias)","an":"1910","u":"Capítulo 1","te":["sufrimiento","memoria","trauma"]},{"i":"sigmund-freud-049","a":"sigmund-freud","t":"La interpretación de los sueños es, en realidad, la vía regia hacia el conocimiento de lo inconsciente, el fundamento más seguro del psicoanálisis.","o":"Die Traumdeutung ist in Wirklichkeit die Via Regia zur Kenntnis des Unbewußten, die sicherste Grundlage der Psychoanalyse","l":"de","ob":"Sobre psicoanálisis (Cinco conferencias)","an":"1910","u":"Capítulo 3","te":["suenos","inconsciente"]},{"i":"william-james-001","a":"william-james","t":"El hábito es así el enorme volante de la sociedad, su más preciado agente conservador.","o":"Habit is thus the enormous fly-wheel of society, its most precious conservative agent.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","sociedad"]},{"i":"william-james-002","a":"william-james","t":"Lo importante en toda educación es hacer de nuestro sistema nervioso un aliado y no un enemigo.","o":"make our nervous system our ally instead of our enemy","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","educacion"]},{"i":"william-james-003","a":"william-james","t":"Si los jóvenes comprendieran qué pronto se convertirán en meros manojos ambulantes de hábitos, prestarían más atención a su conducta mientras todavía son moldeables.","o":"Could the young but realize how soon they will become mere walking bundles of habits, they would give more heed to their conduct while in the plastic state.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","desarrollo-humano"]},{"i":"william-james-004","a":"william-james","t":"Estamos hilando nuestro propio destino, bueno o malo, y no hay manera de deshacerlo.","o":"We are spinning our own fates, good or evil, and never to be undone.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","responsabilidad"]},{"i":"william-james-005","a":"william-james","t":"Cada mínimo trazo de virtud o de vicio deja su cicatriz, por pequeña que sea.","o":"Every smallest stroke of virtue or of vice leaves its never so little scar.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","identidad"]},{"i":"william-james-006","a":"william-james","t":"No permitas ninguna excepción hasta que el nuevo hábito esté firmemente arraigado en tu vida.","o":"Never suffer an exception to occur till the new habit is securely rooted in your life","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","cambio"]},{"i":"william-james-007","a":"william-james","t":"Aprovechá la primera oportunidad posible para actuar según cada resolución que tomes.","o":"Seize the very first possible opportunity to act on every resolution you make","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","cambio"]},{"i":"william-james-008","a":"william-james","t":"Mantené viva en vos la capacidad de esfuerzo con un pequeño ejercicio gratuito cada día.","o":"Keep the faculty of effort alive in you by a little gratuitous exercise every day","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","voluntad"]},{"i":"william-james-009","a":"william-james","t":"[La conciencia] no está hecha de piezas articuladas: fluye. “Río” o “corriente” son las metáforas que mejor la describen.","o":"It is nothing jointed; it flows. A 'river' or a 'stream' are the metaphors by which it is most naturally described.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia"]},{"i":"william-james-010","a":"william-james","t":"Llamémosla corriente del pensamiento, de la conciencia o de la vida subjetiva.","o":"let us call it the stream of thought, of consciousness, or of subjective life","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia"]},{"i":"william-james-011","a":"william-james","t":"Todo pensamiento tiende a formar parte de una conciencia personal.","o":"Every thought tends to be part of a personal consciousness.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia","identidad"]},{"i":"william-james-012","a":"william-james","t":"Ningún estado, una vez pasado, puede repetirse idéntico a lo que fue.","o":"no state once gone can recur and be identical with what it was before","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia","cambio"]},{"i":"william-james-013","a":"william-james","t":"Mi experiencia es aquello a lo que acepto prestar atención.","o":"My experience is what I agree to attend to.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-014","a":"william-james","t":"Sin un interés selectivo, la experiencia es un caos absoluto.","o":"without selective interest, experience is an utter chaos","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-015","a":"william-james","t":"Todo el mundo sabe qué es la atención.","o":"Every one knows what attention is.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion"]},{"i":"william-james-016","a":"william-james","t":"La capacidad de traer de vuelta voluntariamente una atención que se dispersa, una y otra vez, es la raíz misma del juicio, del carácter y de la voluntad.","o":"the faculty of voluntarily bringing back a wandering attention, over and over again, is the very root of judgment, character, and will","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","voluntad","presencia"]},{"i":"william-james-017","a":"william-james","t":"Una persona tiene tantos “yo” sociales como individuos la reconocen.","o":"a man has as many social selves as there are individuals who recognize him","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["identidad","vinculos"]},{"i":"william-james-018","a":"william-james","t":"En su sentido más amplio, el “sí mismo” de una persona es la suma total de todo lo que puede llamar suyo.","o":"a man's Self is the sum total of all that he","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["identidad"]},{"i":"william-james-019","a":"william-james","t":"Autoestima = éxito / pretensiones.","o":"Self-esteem = Success/ Pretensions.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["autoestima","identidad"]},{"i":"william-james-020","a":"william-james","t":"Renunciar a las pretensiones es un alivio tan bendito como verlas satisfechas.","o":"To give up pretensions is as blessed a relief as to get them gratified","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["autoestima","aceptacion"]},{"i":"william-james-021","a":"william-james","t":"El bebé, asaltado a la vez por ojos, oídos, nariz, piel y entrañas, lo siente todo como una gran confusión floreciente y zumbante.","o":"The baby, assailed by eyes, ears, nose, skin, and entrails at once, feels it all as one great blooming, buzzing confusion","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 13","te":["desarrollo-humano","infancia"]},{"i":"william-james-045","a":"william-james","t":"Solo el interés da acento y énfasis, luz y sombra, fondo y primer plano.","o":"Interest alone gives accent and emphasis, light and shade, background and foreground","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-048","a":"william-james","t":"Solo las cosas que noto le dan forma a mi mente.","o":"Only those items which I","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-049","a":"william-james","t":"El infierno que nos espera en el más allá, del que habla la teología, no es peor que el infierno que nos fabricamos en este mundo al moldear habitualmente nuestro carácter de la manera equivocada.","o":"The hell to be endured hereafter, of which theology tells, is no worse than the hell we make for ourselves in this world by habitually fashioning our characters in the wrong way.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","sufrimiento","responsabilidad"]},{"i":"william-james-022","a":"william-james","t":"El arte de ser sabio es el arte de saber qué pasar por alto.","o":"the art of being wise is the art of knowing what to overlook","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 22","te":["atencion","conocimiento"]},{"i":"william-james-023","a":"william-james","t":"Nos sentimos tristes porque lloramos, enojados porque golpeamos, asustados porque temblamos.","o":"we feel sorry because we cry, angry because we strike, afraid because we tremble","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 25","te":["emociones","cuerpo"]},{"i":"william-james-024","a":"william-james","t":"Una emoción humana puramente desencarnada no es nada.","o":"A purely disembodied human emotion is a nonentity.","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 25","te":["emociones","cuerpo"]},{"i":"william-james-025","a":"william-james","t":"Si queremos vencer tendencias emocionales indeseadas, debemos atravesar con asiduidad, y al principio a sangre fría, los movimientos externos de las disposiciones contrarias que preferimos cultivar.","o":"we must assiduously, and in the first instance cold-bloodedly, go through the","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 25","te":["regulacion-emocional","habitos"]},{"i":"william-james-026","a":"william-james","t":"El logro esencial de la voluntad es atender a un objeto difícil y sostenerlo firme ante la mente.","o":"to_ ATTEND _to a difficult object and hold it fast before the mind","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 26","te":["atencion","voluntad"]},{"i":"william-james-047","a":"william-james","t":"Así como el arte de leer (a partir de cierta etapa de la formación) es el arte de saltear…","o":"As the art of reading (after a certain stage in one's education) is the art of skipping","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 22","te":["educacion","atencion"]},{"i":"william-james-050","a":"william-james","t":"El genio, en verdad, no es mucho más que la capacidad de percibir de una manera no habitual.","o":"Genius, in truth, means little more than the faculty of perceiving in an unhabitual way.","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 19","te":["creatividad","conciencia"]},{"i":"william-james-041","a":"william-james","t":"[La religión significará para nosotros] los sentimientos, actos y experiencias de las personas en su soledad, en la medida en que se perciben en relación con lo que consideren divino.","o":"the feelings, acts, and experiences of individual men in their solitude, so far as they apprehend themselves to stand in relation to whatever they may consider the divine","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 2","te":["trascendencia","soledad"]},{"i":"william-james-042","a":"william-james","t":"[Nuestra conciencia de vigilia] no es más que un tipo especial de conciencia; a su alrededor, separadas por la más fina de las pantallas, hay formas potenciales de conciencia completamente distintas.","o":"is but one special type of consciousness, whilst all about it, parted from it by the filmiest of screens, there lie potential forms of consciousness entirely different","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 13","te":["conciencia","trascendencia"]},{"i":"william-james-043","a":"william-james","t":"El mundo de nuestra conciencia presente es solo uno entre muchos mundos de conciencia que existen.","o":"the world of our present consciousness is only one out of many worlds of consciousness that exist","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 20","te":["conciencia"]},{"i":"william-james-044","a":"william-james","t":"La religión, sea lo que sea, es la reacción total de una persona ante la vida.","o":"Religion, whatever it is, is a man's total reaction upon life","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 2","te":["trascendencia","sentido-de-vida"]},{"i":"william-james-038","a":"william-james","t":"La verdad de una idea no es una propiedad estancada que le es inherente. La verdad le sucede a una idea: se vuelve verdadera, los acontecimientos la hacen verdadera.","o":"The truth of an idea is not a stagnant property inherent in it. Truth HAPPENS to an idea. It BECOMES true, is MADE true by events.","l":"en","ob":"Pragmatismo","an":"1907","u":"Conferencia 6","te":["verdad"]},{"i":"william-james-039","a":"william-james","t":"Como seres humanos, podemos ser mentes sanas un día y almas enfermas al siguiente.","o":"as human beings we can be healthy minds on one day and sick souls on the next","l":"en","ob":"Pragmatismo","an":"1907","u":"Conferencia 8","te":["salud-mental","sufrimiento"]},{"i":"william-james-040","a":"william-james","t":"Cualquiera sea el universo en que crea un profesor, tiene que ser al menos un universo que se preste a discursos largos.","o":"Whatever universe a professor believes in must at any rate be a universe that lends itself to lengthy discourse.","l":"en","ob":"Pragmatismo","an":"1907","u":"Conferencia 1","te":["educacion","humor"]},{"i":"william-james-027","a":"william-james","t":"Dondequiera que un proceso vital le comunica entusiasmo a quien lo vive, allí la vida se vuelve verdaderamente significativa.","o":"Wherever a process of life communicates an eagerness to him who lives it, there the life becomes genuinely significant.","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["sentido-de-vida","alegria"]},{"i":"william-james-028","a":"william-james","t":"Ni toda la verdad ni todo el bien se revelan a un solo observador.","o":"neither the whole of truth nor the whole of good is revealed to any single observer","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["verdad","encuentro"]},{"i":"william-james-029","a":"william-james","t":"La ceguera que todos padecemos respecto de los sentimientos de criaturas y personas distintas de nosotros.","o":"the blindness with which we all are afflicted in regard to the feelings of creatures and people different from ourselves","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["empatia","vinculos"]},{"i":"william-james-030","a":"william-james","t":"La acción parece seguir al sentimiento, pero en realidad acción y sentimiento van juntos.","o":"Action seems to follow feeling, but really action and feeling go together","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«The Gospel Of Relaxation»","te":["emociones","regulacion-emocional"]},{"i":"william-james-031","a":"william-james","t":"El camino voluntario soberano hacia la alegría, si perdimos la espontánea, es enderezarnos con alegría, mirar alrededor con alegría [y actuar y hablar como si ya estuviera allí].","o":"the sovereign voluntary path to cheerfulness, if our spontaneous cheerfulness be lost, is to sit up cheerfully, to look round cheerfully","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«The Gospel Of Relaxation»","te":["alegria","regulacion-emocional"]},{"i":"william-james-032","a":"william-james","t":"Somos seres prácticos, cada uno con funciones y deberes limitados que cumplir.","o":"We are practical beings, each of us with limited functions and duties to perform.","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["trabajo","identidad"]},{"i":"william-james-046","a":"william-james","t":"Cada recaída es como dejar caer un ovillo que uno estaba enrollando con cuidado.","o":"Each lapse is like the letting fall of a ball of string which one is carefully winding up","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«The Laws Of Habit»","te":["habitos","cambio"]},{"i":"william-james-033","a":"william-james","t":"No le tengas miedo a la vida. Creé que la vida vale la pena, y tu creencia ayudará a crear el hecho.","o":"Be not afraid of life. Believe that life","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["sentido-de-vida","miedo","esperanza"]},{"i":"william-james-034","a":"william-james","t":"Solo arriesgándonos de una hora a la otra vivimos realmente.","o":"It is only by risking our persons from one hour to another that we live at all.","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["libertad","incertidumbre"]},{"i":"william-james-035","a":"william-james","t":"A menudo, nuestra fe anticipada en un resultado incierto es lo único que hace que el resultado se cumpla.","o":"our faith beforehand in an uncertified result","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["esperanza","incertidumbre"]},{"i":"william-james-036","a":"william-james","t":"Nuestra naturaleza pasional no solo puede legítimamente, sino que debe, decidir entre proposiciones [cuando se trata de una opción genuina que el intelecto no puede zanjar].","o":"Our passional nature not only lawfully may, but must, decide an option between propositions","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«The Will To Believe»","te":["deseo","verdad","libertad"]},{"i":"william-james-037","a":"william-james","t":"Podemos decir que esta vida vale la pena, ya que es lo que hacemos de ella, desde el punto de vista moral.","o":"This life is worth living, we can say,","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["sentido-de-vida","responsabilidad"]},{"i":"william-james-051","a":"william-james","t":"Una regla de pensamiento que me impidiera absolutamente reconocer ciertos tipos de verdad, si esas verdades realmente existieran, [sería una regla irracional].","o":"a rule of thinking which would absolutely prevent me from acknowledging certain kinds of truth if those kinds of truth were really there","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«The Will To Believe»","te":["verdad","conocimiento"]}],"ruta":"/recursos/voces-que-nos-habitan/","temasRuta":"/recursos/voces-que-nos-habitan/temas/","escuelas":[["fil","Filosofía"],["ini","Los comienzos"],["pa","Psicoanálisis"]],"epocas":[["clasico","Clásicos"],["moderno","Modernos"]]};
